import React from "react";
import {
  FaCode,
  FaAward,
  FaBriefcase,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain,
  FaChartLine
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      {/* HEADER */}
      <div className="header">
        <h1>Skills & Journey</h1>
        <p>My technical foundation, certifications, and real-world internship experience.</p>
      </div>

      {/* MAIN TIMELINE LAYOUT */}
      <div className="timeline">

        {/* TECH SKILLS */}
        <div className="timeline-item">
          <div className="dot"></div>
          <div className="card">
            <h2><FaCode /> Technical Skills</h2>
            <div className="tags">
              <span>Java</span>
              <span>React.js</span>
              <span>Spring Boot</span>
              <span>MySQL</span>
              <span>HTML & CSS</span>
            </div>
          </div>
        </div>

        {/* CERTIFICATIONS */}
        <div className="timeline-item">
          <div className="dot"></div>
          <div className="card">
            <h2><FaAward /> Certifications</h2>
            <div className="tags">
              <span>Java – NPTEL</span>
              <span>Data Science for Engineers – NPTEL</span>
              <span>SQL – HackerRank</span>
              <span>Python – SoloLearn</span>
            </div>
          </div>
        </div>

        {/* INTERNSHIP 1 */}
        <div className="timeline-item">
          <div className="dot"></div>
          <div className="card">
            <h2><FaBriefcase /> Full Stack Internship</h2>
            <span className="company">Retech Solutions</span>

            <p>
              Worked on Full Stack Java development using Spring Boot.
              Built REST APIs, managed database operations, and developed
              a Student Portal Management System with structured backend logic.
            </p>
          </div>
        </div>

        {/* INTERNSHIP 2 */}
        <div className="timeline-item">
          <div className="dot"></div>
          <div className="card">
            <h2><FaChartLine /> Data Analytics Internship</h2>
            <span className="company">Power BI Program</span>

            <p>
              Completed internship in Data Analytics with Power BI.
              Created interactive dashboards, performed data cleaning,
              and transformed raw datasets into meaningful insights for decision-making.
            </p>
          </div>
        </div>

        {/* SOFT SKILLS */}
        <div className="timeline-item">
          <div className="dot"></div>
          <div className="card">
            <h2><FaUsers /> Soft Skills</h2>

            <div className="tags">
              <span>Teamwork</span>
              <span>Communication</span>
              <span>Problem Solving</span>
              <span>Adaptability</span>
              <span>Creativity</span>
              <span>Leadership</span>
              <span>Time Management</span>
            </div>
          </div>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .skills-page {
          min-height: 100vh;
          padding: 40px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 50px;
        }

        .header h1 {
          font-size: 42px;
          color: #38BDF8;
        }

        .header p {
          color: #94a3b8;
          margin-top: 10px;
        }

        /* TIMELINE */
        .timeline {
          position: relative;
          display: flex;
          flex-direction: column;
          gap: 30px;
          padding-left: 40px;
          border-left: 2px solid rgba(56,189,248,0.3);
        }

        .timeline-item {
          position: relative;
        }

        /* DOT */
        .dot {
          position: absolute;
          left: -50px;
          top: 10px;
          width: 14px;
          height: 14px;
          background: #38BDF8;
          border-radius: 50%;
          box-shadow: 0 0 12px #38BDF8;
        }

        /* CARD */
        .card {
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          padding: 20px;
          border-radius: 16px;
          backdrop-filter: blur(10px);
          transition: 0.3s;
        }

        .card:hover {
          transform: translateY(-5px);
          border-color: #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
        }

        /* TITLE */
        h2 {
          display: flex;
          align-items: center;
          gap: 10px;
          color: #38BDF8;
          margin-bottom: 10px;
        }

        /* COMPANY */
        .company {
          display: inline-block;
          padding: 4px 10px;
          margin-bottom: 10px;
          font-size: 12px;
          border-radius: 12px;
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
        }

        /* TEXT */
        p {
          color: #cbd5e1;
          font-size: 14px;
          line-height: 1.6;
        }

        /* TAGS */
        .tags {
          display: flex;
          flex-wrap: wrap;
          gap: 10px;
          margin-top: 10px;
        }

        .tags span {
          font-size: 13px;
          padding: 6px 12px;
          border-radius: 20px;
          background: rgba(56,189,248,0.1);
          border: 1px solid rgba(56,189,248,0.3);
          color: #cbd5e1;
        }

        @media (max-width: 900px) {
          .timeline {
            padding-left: 20px;
          }

          .dot {
            left: -30px;
          }
        }

      `}</style>

    </section>
  );
};

export default Skills;
